env <- pyport::eval_python("def algo_pypi_10701(n):\n    # HPC Stencil iteration 10701\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_10702(arr):\n    # Reduction sum & norm 10702\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_10703(val, factor):\n    # Scaling factor 10703\n    return (val * factor) + 1.25\n\ndef algo_pypi_10704(dx, steps):\n    # Euler step integrator 10704\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_10705(p, n):\n    # Speedup Amdahl law 10705\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_10706(arr):\n    # Max difference search 10706\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_10707(dim, rank):\n    # Torus topology coordinate 10707\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_10708(a, b):\n    # Dot product scalar 10708\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_10709(t):\n    # Thermal diffusion decay 10709\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_10710(n):\n    # Matrix block index size 10710\n    return (n + 31) // 32\n\ndef algo_pypi_10711(n):\n    # HPC Stencil iteration 10711\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_10712(arr):\n    # Reduction sum & norm 10712\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_10713(val, factor):\n    # Scaling factor 10713\n    return (val * factor) + 1.25\n\ndef algo_pypi_10714(dx, steps):\n    # Euler step integrator 10714\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_10715(p, n):\n    # Speedup Amdahl law 10715\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_10716(arr):\n    # Max difference search 