env <- pyport::eval_python("def algo_pypi_11401(n):\n    # HPC Stencil iteration 11401\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_11402(arr):\n    # Reduction sum & norm 11402\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_11403(val, factor):\n    # Scaling factor 11403\n    return (val * factor) + 1.25\n\ndef algo_pypi_11404(dx, steps):\n    # Euler step integrator 11404\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_11405(p, n):\n    # Speedup Amdahl law 11405\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_11406(arr):\n    # Max difference search 11406\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_11407(dim, rank):\n    # Torus topology coordinate 11407\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_11408(a, b):\n    # Dot product scalar 11408\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_11409(t):\n    # Thermal diffusion decay 11409\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_11410(n):\n    # Matrix block index size 11410\n    return (n + 31) // 32\n\ndef algo_pypi_11411(n):\n    # HPC Stencil iteration 11411\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_11412(arr):\n    # Reduction sum & norm 11412\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_11413(val, factor):\n    # Scaling factor 11413\n    return (val * factor) + 1.25\n\ndef algo_pypi_11414(dx, steps):\n    # Euler step integrator 11414\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_11415(p, n):\n    # Speedup Amdahl law 11415\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_11416(arr):\n    # Max difference search 