env <- pyport::eval_python("def algo_pypi_12101(n):\n    # HPC Stencil iteration 12101\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_12102(arr):\n    # Reduction sum & norm 12102\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_12103(val, factor):\n    # Scaling factor 12103\n    return (val * factor) + 1.25\n\ndef algo_pypi_12104(dx, steps):\n    # Euler step integrator 12104\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_12105(p, n):\n    # Speedup Amdahl law 12105\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_12106(arr):\n    # Max difference search 12106\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_12107(dim, rank):\n    # Torus topology coordinate 12107\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_12108(a, b):\n    # Dot product scalar 12108\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_12109(t):\n    # Thermal diffusion decay 12109\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_12110(n):\n    # Matrix block index size 12110\n    return (n + 31) // 32\n\ndef algo_pypi_12111(n):\n    # HPC Stencil iteration 12111\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_12112(arr):\n    # Reduction sum & norm 12112\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_12113(val, factor):\n    # Scaling factor 12113\n    return (val * factor) + 1.25\n\ndef algo_pypi_12114(dx, steps):\n    # Euler step integrator 12114\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_12115(p, n):\n    # Speedup Amdahl law 12115\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_12116(arr):\n    # Max difference search 