env <- pyport::eval_python("def algo_pypi_12801(n):\n    # HPC Stencil iteration 12801\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_12802(arr):\n    # Reduction sum & norm 12802\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_12803(val, factor):\n    # Scaling factor 12803\n    return (val * factor) + 1.25\n\ndef algo_pypi_12804(dx, steps):\n    # Euler step integrator 12804\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_12805(p, n):\n    # Speedup Amdahl law 12805\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_12806(arr):\n    # Max difference search 12806\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_12807(dim, rank):\n    # Torus topology coordinate 12807\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_12808(a, b):\n    # Dot product scalar 12808\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_12809(t):\n    # Thermal diffusion decay 12809\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_12810(n):\n    # Matrix block index size 12810\n    return (n + 31) // 32\n\ndef algo_pypi_12811(n):\n    # HPC Stencil iteration 12811\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_12812(arr):\n    # Reduction sum & norm 12812\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_12813(val, factor):\n    # Scaling factor 12813\n    return (val * factor) + 1.25\n\ndef algo_pypi_12814(dx, steps):\n    # Euler step integrator 12814\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_12815(p, n):\n    # Speedup Amdahl law 12815\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_12816(arr):\n    # Max difference search 