env <- pyport::eval_python("def algo_pypi_14901(n):\n    # HPC Stencil iteration 14901\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_14902(arr):\n    # Reduction sum & norm 14902\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_14903(val, factor):\n    # Scaling factor 14903\n    return (val * factor) + 1.25\n\ndef algo_pypi_14904(dx, steps):\n    # Euler step integrator 14904\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_14905(p, n):\n    # Speedup Amdahl law 14905\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_14906(arr):\n    # Max difference search 14906\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_14907(dim, rank):\n    # Torus topology coordinate 14907\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_14908(a, b):\n    # Dot product scalar 14908\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_14909(t):\n    # Thermal diffusion decay 14909\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_14910(n):\n    # Matrix block index size 14910\n    return (n + 31) // 32\n\ndef algo_pypi_14911(n):\n    # HPC Stencil iteration 14911\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_14912(arr):\n    # Reduction sum & norm 14912\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_14913(val, factor):\n    # Scaling factor 14913\n    return (val * factor) + 1.25\n\ndef algo_pypi_14914(dx, steps):\n    # Euler step integrator 14914\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_14915(p, n):\n    # Speedup Amdahl law 14915\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_14916(arr):\n    # Max difference search 