env <- pyport::eval_python("def algo_pypi_15601(n):\n    # HPC Stencil iteration 15601\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_15602(arr):\n    # Reduction sum & norm 15602\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_15603(val, factor):\n    # Scaling factor 15603\n    return (val * factor) + 1.25\n\ndef algo_pypi_15604(dx, steps):\n    # Euler step integrator 15604\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_15605(p, n):\n    # Speedup Amdahl law 15605\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_15606(arr):\n    # Max difference search 15606\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_15607(dim, rank):\n    # Torus topology coordinate 15607\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_15608(a, b):\n    # Dot product scalar 15608\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_15609(t):\n    # Thermal diffusion decay 15609\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_15610(n):\n    # Matrix block index size 15610\n    return (n + 31) // 32\n\ndef algo_pypi_15611(n):\n    # HPC Stencil iteration 15611\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_15612(arr):\n    # Reduction sum & norm 15612\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_15613(val, factor):\n    # Scaling factor 15613\n    return (val * factor) + 1.25\n\ndef algo_pypi_15614(dx, steps):\n    # Euler step integrator 15614\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_15615(p, n):\n    # Speedup Amdahl law 15615\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_15616(arr):\n    # Max difference search 