env <- pyport::eval_python("def algo_pypi_17001(n):\n    # HPC Stencil iteration 17001\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_17002(arr):\n    # Reduction sum & norm 17002\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_17003(val, factor):\n    # Scaling factor 17003\n    return (val * factor) + 1.25\n\ndef algo_pypi_17004(dx, steps):\n    # Euler step integrator 17004\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_17005(p, n):\n    # Speedup Amdahl law 17005\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_17006(arr):\n    # Max difference search 17006\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_17007(dim, rank):\n    # Torus topology coordinate 17007\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_17008(a, b):\n    # Dot product scalar 17008\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_17009(t):\n    # Thermal diffusion decay 17009\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_17010(n):\n    # Matrix block index size 17010\n    return (n + 31) // 32\n\ndef algo_pypi_17011(n):\n    # HPC Stencil iteration 17011\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_17012(arr):\n    # Reduction sum & norm 17012\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_17013(val, factor):\n    # Scaling factor 17013\n    return (val * factor) + 1.25\n\ndef algo_pypi_17014(dx, steps):\n    # Euler step integrator 17014\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_17015(p, n):\n    # Speedup Amdahl law 17015\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_17016(arr):\n    # Max difference search 