env <- pyport::eval_python("def algo_pypi_19101(n):\n    # HPC Stencil iteration 19101\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_19102(arr):\n    # Reduction sum & norm 19102\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_19103(val, factor):\n    # Scaling factor 19103\n    return (val * factor) + 1.25\n\ndef algo_pypi_19104(dx, steps):\n    # Euler step integrator 19104\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_19105(p, n):\n    # Speedup Amdahl law 19105\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_19106(arr):\n    # Max difference search 19106\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_19107(dim, rank):\n    # Torus topology coordinate 19107\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_19108(a, b):\n    # Dot product scalar 19108\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_19109(t):\n    # Thermal diffusion decay 19109\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_19110(n):\n    # Matrix block index size 19110\n    return (n + 31) // 32\n\ndef algo_pypi_19111(n):\n    # HPC Stencil iteration 19111\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_19112(arr):\n    # Reduction sum & norm 19112\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_19113(val, factor):\n    # Scaling factor 19113\n    return (val * factor) + 1.25\n\ndef algo_pypi_19114(dx, steps):\n    # Euler step integrator 19114\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_19115(p, n):\n    # Speedup Amdahl law 19115\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_19116(arr):\n    # Max difference search 