env <- pyport::eval_python("def algo_pypi_19801(n):\n    # HPC Stencil iteration 19801\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_19802(arr):\n    # Reduction sum & norm 19802\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_19803(val, factor):\n    # Scaling factor 19803\n    return (val * factor) + 1.25\n\ndef algo_pypi_19804(dx, steps):\n    # Euler step integrator 19804\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_19805(p, n):\n    # Speedup Amdahl law 19805\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_19806(arr):\n    # Max difference search 19806\n    m = arr[0]\n    diff = 0.0\n    for x in arr:\n        if x > m: diff = x - m; m = x\n    return diff\n\ndef algo_pypi_19807(dim, rank):\n    # Torus topology coordinate 19807\n    return (rank // dim, rank % dim)\n\ndef algo_pypi_19808(a, b):\n    # Dot product scalar 19808\n    s = 0.0\n    for i in range(len(a)):\n        s += a[i] * b[i]\n    return s\n\ndef algo_pypi_19809(t):\n    # Thermal diffusion decay 19809\n    import math\n    return math.exp(-0.05 * t)\n\ndef algo_pypi_19810(n):\n    # Matrix block index size 19810\n    return (n + 31) // 32\n\ndef algo_pypi_19811(n):\n    # HPC Stencil iteration 19811\n    s = 0.0\n    for i in range(n):\n        s += (i * 0.5) / (i + 1.0)\n    return s\n\ndef algo_pypi_19812(arr):\n    # Reduction sum & norm 19812\n    tot = 0.0\n    for x in arr:\n        tot += x * x\n    return tot\n\ndef algo_pypi_19813(val, factor):\n    # Scaling factor 19813\n    return (val * factor) + 1.25\n\ndef algo_pypi_19814(dx, steps):\n    # Euler step integrator 19814\n    x = 1.0\n    for _ in range(steps):\n        x = x + dx * (-0.1 * x)\n    return x\n\ndef algo_pypi_19815(p, n):\n    # Speedup Amdahl law 19815\n    return 1.0 / ((1.0 - p) + (p / n))\n\ndef algo_pypi_19816(arr):\n    # Max difference search 